@startuml

class Researcher {
  + name : string
  + surname : string
  + researchGroup : ResearchGroup
}

class ResearchGroup {
  + name : string
  + department : Department
}

class Department {
  + name : string
  + university : University
}

class WorkPackage {
  + id : int
  + title : string
  + leader : ResearchGroup
}

class Assignment {
  + researcher : Researcher
  + workPackage : WorkPackage
  + startDate : date
  + endDate : date
}

University "1" *-- "*" Department
Department "1" *-- "*" ResearchGroup
ResearchGroup "1" -- "*" Researcher
WorkPackage "1" -- "1" ResearchGroup : leads
Researcher "0..*" -- "1..*" Assignment

@enduml

